/** message.op : op  at AbsoluteStatic(0x01)
 * size=Fixed(1) align=Aligned(1) repr=MemoryIdentical atomic=AtomicWord mutate=InPlaceFixed
 */
static inline fzn_search_wire_op_t fzn_search_wire_message_op_get(situ_view_t view)
{
	return (fzn_search_wire_op_t)((uint8_t)(situ_base(view))[1u]);
}
/* No plain setter: `op` decides where later members
 * start, so writing it must invalidate outstanding views. Use
 * fzn_search_wire_message_op_set(),
 * which takes the message and bumps its generation. */

/* message.body : variant  at AbsoluteStatic(0x02)
 * size=Bounded(2, 9952) align=Aligned(2) repr=MemoryIdentical atomic=NonAtomic mutate=Shifting
 */
/* `body` is a variant: exactly one of `ask`, `answer` is
 * present, and which one is in the discriminant. The variant has no
 * accessor of its own -- there is no one thing to hand back -- and
 * each arm's members are below, guarded. */

/* message.body.ask, present when the discriminant selects `op.ask`.
 *
 * Reading another arm's bytes as this one's stays inside the view
 * and means nothing, so the accessor asks first and refuses. The
 * code is `default: error`'s, being the same mistake from the
 * other end. */
/** How many bytes `ask` occupies, for the switch
 * that places whatever follows the variant.
 */
static inline uint32_t fzn_search_wire_message_body_ask_extent(situ_view_t view)
{
	situ_view_t whole;

	if (situ_view_sub(view, 2u, situ_remaining_u32(view.limit, 2u), &whole) != SITU_OK) {
		return 0u;
	}
	return fzn_search_wire_ask_extent(whole);
}
static inline situ_err_t fzn_search_wire_message_body_ask_view(situ_view_t view, situ_view_t *out)
{
	if (fzn_search_wire_message_op_get(view) != 1u) {
		return SITU_ERR_VERSION;
	}
	situ_view_t whole;

	if (situ_view_sub(view, 2u, situ_remaining_u32(view.limit, 2u), &whole) != SITU_OK) {
		return SITU_ERR_BOUNDS;
	}
	const uint32_t size = fzn_search_wire_ask_extent(whole);
	return situ_view_sub(view, 2u, size, out);
}

